mapper.select:
SELECT COUNT(*)
FROM h_message_feedbacks

    WHERE rating = #{rating}

choose.when:
SELECT TO_CHAR(hc.updated_at + INTERVAL '8 hours',
'YYYY-MM-DD HH24:00' 'IYYY-IW' 'YYYY-MM-DD'
) AS "date", COUNT(*) AS "count", COALESCE(hc.agent_id, 'unknown_agent') AS "category" FROM h_conversations hc WHERE hc.updated_at IS NOT NULL AND hc.updated_at >= #{startTime} GROUP BY 1, 3 ORDER BY 1

SELECT TO_CHAR(hm.created_at + INTERVAL '8 hours',
'YYYY-MM-DD HH24:00' 'IYYY-IW' 'YYYY-MM-DD'
) AS "date", SUM(COALESCE((hm.extra_metadata -> 'usage_metadata' ->> 'input_tokens')::BIGINT, 0)) AS "count", 'input_tokens' AS "category" FROM h_messages hm INNER JOIN h_conversations hc ON hc.id = hm.conversation_id WHERE hm.created_at >= #{startTime} AND hm.extra_metadata IS NOT NULL AND hm.extra_metadata -> 'usage_metadata' IS NOT NULL GROUP BY 1 UNION ALL SELECT TO_CHAR(hm.created_at + INTERVAL '8 hours',
'YYYY-MM-DD HH24:00' 'IYYY-IW' 'YYYY-MM-DD'
) AS "date", SUM(COALESCE((hm.extra_metadata -> 'usage_metadata' ->> 'output_tokens')::BIGINT, 0)) AS "count", 'output_tokens' AS "category" FROM h_messages hm INNER JOIN h_conversations hc ON hc.id = hm.conversation_id WHERE hm.created_at >= #{startTime} AND hm.extra_metadata IS NOT NULL AND hm.extra_metadata -> 'usage_metadata' IS NOT NULL GROUP BY 1 ORDER BY 1

SELECT TO_CHAR(htc.created_at + INTERVAL '8 hours',
'YYYY-MM-DD HH24:00' 'IYYY-IW' 'YYYY-MM-DD'
) AS "date", COUNT(*) AS "count", COALESCE(htc.tool_name, 'unknown_tool') AS "category" FROM h_tool_calls htc INNER JOIN h_messages hm ON hm.id = htc.message_id INNER JOIN h_conversations hc ON hc.id = hm.conversation_id WHERE htc.created_at >= #{startTime} GROUP BY 1, 3 ORDER BY 1

choose.otherwise:
SELECT TO_CHAR(hm.created_at + INTERVAL '8 hours',
'YYYY-MM-DD HH24:00' 'IYYY-IW' 'YYYY-MM-DD'
) AS "date", COUNT(*) AS "count", hm.extra_metadata -> 'response_metadata' ->> 'model_name' AS "category" FROM h_messages hm INNER JOIN h_conversations hc ON hc.id = hm.conversation_id WHERE hm.role = 'assistant' AND hm.created_at >= #{startTime} AND hm.extra_metadata IS NOT NULL GROUP BY 1, 3 ORDER BY 1

mapper.select:
SELECT COUNT(*)
FROM h_tool_calls htc
         INNER JOIN h_messages hm ON hm.id = htc.message_id
         INNER JOIN h_conversations hc ON hc.id = hm.conversation_id


        AND htc.status = #{status}


        AND htc.created_at >= #{since}


        AND htc.created_at < #{until}

SELECT DISTINCT ON (slug) slug AS "agentId", name FROM h_agents WHERE slug IN
#{slug}
ORDER BY slug, tenant_id NULLS FIRST

SELECT COUNT(*) FROM ( SELECT s.user_id FROM sessions s INNER JOIN users u ON u.id = s.user_id AND u.deleted_at IS NULL WHERE s.deleted_at IS NULL AND s.user_id IS NOT NULL AND s.user_id <> '' AND s.updated_at >= #{since}
AND s.updated_at < #{until}
UNION SELECT s.user_id FROM messages m INNER JOIN sessions s ON s.id = m.session_id INNER JOIN users u ON u.id = s.user_id AND u.deleted_at IS NULL WHERE m.deleted_at IS NULL AND s.deleted_at IS NULL AND s.user_id IS NOT NULL AND s.user_id <> '' AND m.created_at >= #{since}
AND m.created_at < #{until}
) active_users
